	"strings"
)

// getTargetForRedirect checks if the provided target URL string is within the provided domain.
// If so, it returns the target URL for redirect; otherwise, it falls back to the domain URL for redirect.
// It uses the https protocol.
//
// Examples:
//
//	getTargetForRedirect("https://music.example.com", "example.com") -> "https://music.example.com"
//	getTargetForRedirect("https://example.com/service", "example.com") -> "https://example.com/service"
//	getTargetForRedirect("https://blog.example.com/posts", "example.com") -> "https://blog.example.com/posts"
//	getTargetForRedirect("https://another.com", "example.com") -> "https://example.com"
//
// @param target: The target URL string.
// @param domain: The domain string, without protocol.
//
// @return The URL string for redirect.
func getTargetForRedirect(target string, domain string) string {
	// Ensure the domain has a protocol for proper URL parsing.
	// We assume https as per the requirement.
	domainWithProtocol := "https://" + domain

	targetURL, err := url.Parse(target)
	if err != nil {
		// If the target URL is malformed, fall back to the domain URL.
		return domainWithProtocol
	}

	domainURL, err := url.Parse(domainWithProtocol)
	if err != nil {
		// This should ideally not happen if domain is a valid string, but as a safeguard.
		return domainWithProtocol
	}

	// Check if the target URL's host is the same as or a subdomain of the domain URL's host.
	// This also implicitly handles cases where the target URL might be malformed and
	// url.Parse would return an empty host.
	if targetURL.Host == domainURL.Host || strings.HasSuffix(targetURL.Host, "."+domainURL.Host) {
		// Ensure the target URL uses https protocol.
		if targetURL.Scheme == "" || targetURL.Scheme == "http" {
			targetURL.Scheme = "https"
		}
		return targetURL.String()
	}

	// If the target URL is not within the domain, fall back to the domain URL.
	return domainWithProtocol
}
