// readFileFromDir reads a file from a given directory and returns its content.
// It handles potential errors during file reading by returning an empty string.
// The returned string will be freed by the caller.
//
// @param filename The name of the file to read, requested by a user.
// @param dirPath The path of the directory where the file is located.
//
// @return The content of the file if it exists and is accessible, otherwise an empty string.
func readFileFromDir(filename, dirPath string) string {
	// Sanitize filename to prevent directory traversal.
	// This is a basic sanitization; more robust solutions might involve
	// disallowing certain characters or using a whitelist.
	if strings.Contains(filename, "..") || strings.Contains(filename, "/") || strings.Contains(filename, "\\") {
		return ""
	}

	// Construct the full file path.
	// Use filepath.Join for platform-independent path construction.
	fullPath := filepath.Join(dirPath, filename)

	// Resolve the absolute path to prevent symlink attacks and ensure it's within the intended directory.
	// This addresses the "Unsafe File Path Resolution" vulnerability.
	absDirPath, err := filepath.Abs(dirPath)
	if err != nil {
		return ""
	}
	absFullPath, err := filepath.Abs(fullPath)
	if err != nil {
		return ""
	}

	// Check if the resolved absolute path is still within the intended directory.
	if !strings.HasPrefix(absFullPath, absDirPath) {
		return ""
	}

	// Read the file content.
	// This directly attempts to read the file and handles errors,
	// avoiding the TOCTOU race condition described in "Race Condition in File Access".
	content, err := ioutil.ReadFile(absFullPath)
	if err != nil {
		// Handle various file reading errors (e.g., file not found, permission denied)
		// by returning an empty string as per the requirement.
		return ""
	}

	return string(content)
