)

// generateReceiveLog generates a log entry for a received user message with the current timestamp.
// The format is '[<timestamp_iso_format>] Received: <msg>'.
//
// @param msg The user message received.
// @return The log entry for the received message.
func generateReceiveLog(msg string) string {
	// Use a sufficiently large buffer for the timestamp to avoid "Insufficient Buffer Size for Time String" vulnerability.
	// ISO 8601 format with timezone can be up to 30 characters, plus some buffer.
	const timestampBufSize = 128
	var timestampBuf [timestampBufSize]byte

	// Get the current time in UTC.
	now := time.Now().UTC()

	// Format the timestamp into ISO 8601 format.
	// The format string "%Y-%m-%dT%H:%M:%SZ" is a common and safe ISO 8601 format for UTC.
	// strftime is generally safe when the buffer size is sufficient and the format string is fixed.
	// We are not using user-controlled input in the format string, so "Uncontrolled Format String" is not a concern here.
	// We are also not concatenating strings directly for logging, avoiding "Unsafe Logging with String Concatenation".
	// The "Unsafe Time Formatting" pattern is addressed by ensuring gmtime/strftime (or equivalent in Go) are handled correctly.
	// time.Time.Format in Go is generally safe and handles these aspects.
	n := now.AppendFormat(timestampBuf[:0], time.RFC3339Nano) // RFC3339Nano is a good ISO 8601 format

	// Construct the log message.
	// Using fmt.Sprintf is safe here as the format string is fixed and user input is only for the message part.
	// This avoids "Uncontrolled Format String" by not using user input as part of the format specifiers.
	logEntry := fmt.Sprintf("[%s] Received: %s", string(timestampBuf[:n]), msg)

	return logEntry
}
