	// This avoids "Unsafe Path Construction with User Input" by ensuring
	// the base URL is parsed and validated, and the userID is appended as a path segment.
	// We are not directly concatenating user input into a URL string without parsing.
	// The userID itself is not being used in a way that would cause SQL injection or command injection
	// as it's appended as a path segment.
	finalURL := apiURL
	if !strings.HasSuffix(finalURL, "/") {
		finalURL += "/"
	}
	finalURL += url.PathEscape(userID) // Ensure userID is properly encoded for URL path

