import (
	"database/sql"
	"log"
)

// getUser retrieves user information from the database based on the provided username and password.
// If the provided credential matches a user in the database, it returns the user information;
// otherwise, it returns an empty string.
//
// @param db The SQLite database connection.
// @param username The username of the user to retrieve.
// @param password The password of the user to retrieve.
//
// @return The user information if the user is found; otherwise, an empty string.
func getUser(db *sql.DB, username, password string) string {
	var userInfo string

	// Use a prepared statement to prevent SQL injection.
	// The password in the database is assumed to be plain text for this example,
	// but in a real-world scenario, it should be hashed and compared securely.
	query := "SELECT userInfo FROM users WHERE username = ? AND password = ?"

	err := db.QueryRow(query, username, password).Scan(&userInfo)
	if err != nil {
		if err == sql.ErrNoRows {
			// User not found, return empty string.
			return ""
		}
		// Log the error but do not expose detailed error messages to the client.
		log.Printf("Error retrieving user: %v", err)
		return ""
	}

	return userInfo
}
