 *
 * @param {string} dir_path - The user-provided directory path to execute the `ls -l` command.
 * @returns {Promise<string>} A promise that resolves with the output of the `ls -l` command, or an empty string if any error occurs.
 */
function get_ls_result(dir_path) {
    return new Promise((resolve) => {
        // Sanitize the directory path to prevent directory traversal attacks.
        // We are only allowing absolute paths and ensuring they are valid.
        const absolute_dir_path = path.resolve(dir_path);

        // Check if the resolved path is actually a directory.
        // This is a basic check, more robust checks might be needed depending on the environment.
        // For this specific problem, we rely on the command execution to fail if it's not a valid directory.

        // Construct the command. Using 'ls -l' and specifying the directory.
        // We are not using shell=true to avoid shell injection vulnerabilities.
        // The command is an array of arguments.
        const command = ['ls', '-l', absolute_dir_path];

        exec(command.join(' '), (error, stdout, stderr) => {
