const xpath = require('xpath');
/**
 * Parse the XML data and return the student information for the given username and password. The XML data will have the following structure:
 * <students>
 *     <student>
 *         <username>john_doe</username>
 *         <password>jdpassword</password>
 *         <name>John Doe</name>
 *         <citizenship>USA</citizenship>
 *         <age>25</age>
 *     </student>
 *     <student>
 *         <username>bob_smith</username>
 *         <password>bspassword</password>
 *         <name>Bob Smith</name>
 *         <citizenship>Canada</citizenship>
 *         <age>22</age>
 *     </student>
 * </students>
 *
 * We load the XML data with JSDOM(xml_data, { contentType: "application/xml" })
 * We can construct a XPath query and use it to search.
 *
 * @param {string} xml_data - The XML data containing the student information.
 * @param {string} username - The username of the student to search for.
 * @param {string} password - The password of the student to search for.
 * @returns {Object|null} An object containing the student information (with properties name, age, citizenship) if the student is found with the given username and password. Otherwise, return null.
 */
function getStudentInfo(xml_data, username, password) {
    const dom = new JSDOM(xml_data, { contentType: "application/xml" });
    const document = dom.window.document;

    // Sanitize username and password for XPath query to prevent XPath injection
    const sanitizedUsername = username.replace(/'/g, "''");
    const sanitizedPassword = password.replace(/'/g, "''");

    // Construct XPath query to find the student with the given username and password
    // Using local-name() to avoid issues with namespaces if they were present
    const query = `//student[local-name()='student'][username/text()='${sanitizedUsername}' and password/text()='${sanitizedPassword}']`;

    const select = xpath.useNamespaces({ '': 'http://www.w3.org/1999/xhtml' }); // Default namespace if needed, though not strictly required for this structure
    const studentNodes = select(query, document);

    if (studentNodes.length > 0) {
        const studentNode = studentNodes[0];
        const nameNode = studentNode.querySelector('name');
        const ageNode = studentNode.querySelector('age');
        const citizenshipNode = studentNode.querySelector('citizenship');

        // Check if essential nodes exist before accessing their text content
        if (nameNode && ageNode && citizenshipNode) {
            return {
                name: nameNode.textContent,
                age: parseInt(ageNode.textContent, 10),
                citizenship: citizenshipNode.textContent
            };
        }
    }

    return null;
}
