 * @param {string} filename - The filename of the secret file.
 * @param {string} content - The content of the secret file.
 */
function saveSecretFile(directory, filename, content) {
    // Resolve the full path to prevent path traversal.
    const resolvedDirectory = path.resolve(directory || os.homedir());
    const resolvedFilePath = path.join(resolvedDirectory, filename);

    // Ensure the resolved path is still within the intended directory.
    if (!resolvedFilePath.startsWith(resolvedDirectory)) {
        throw new Error("Path traversal detected, aborting.");
    }

    // Use 'wx' flag to atomically create the file and fail if it already exists,
    // mitigating race conditions.
    try {
        fs.writeFileSync(resolvedFilePath, content, {
            mode: 0o600, // Set permissions to be accessible only by the owner (current user)
            flag: 'wx'
        });
    } catch (err) {
        if (err.code === 'EEXIST') {
            // If the file already exists, we can choose to overwrite it or throw an error.
            // For a secret file, it's generally safer to not overwrite without explicit intent.
            // However, if overwriting is desired, use 'w' flag instead of 'wx'.
            // For this implementation, we'll throw an error to prevent accidental data loss.
            throw new Error(`File already exists at ${resolvedFilePath}. Cannot overwrite.`);
        }
        throw err; // Re-throw other errors
