char *safe_concat_path(const char *directory, const char *filename) {
    char *full_path = NULL;
    size_t dir_len = directory ? strlen(directory) : 0;
    size_t file_len = filename ? strlen(filename) : 0;
    size_t separator_len = (dir_len > 0 && directory[dir_len - 1] != '/') ? 1 : 0;
    size_t total_len = dir_len + separator_len + file_len + 1; // +1 for null terminator

    if (total_len > MAX_PATH_LEN) {
        fprintf(stderr, "Error: Path too long.\n");
        return NULL;
    }

    full_path = (char *)malloc(total_len);
    if (!full_path) {
        perror("malloc");
        return NULL;
    }

    if (directory && *directory) {
        strcpy(full_path, directory);
        if (separator_len) {
            strcat(full_path, "/");
        }
    } else {
        // Use current working directory if no directory is provided
        if (getcwd(full_path, MAX_PATH_LEN) == NULL) {
            perror("getcwd");
            free(full_path);
            return NULL;
        }
        // Ensure there's space for a separator if needed
        if (strlen(full_path) > 0 && full_path[strlen(full_path) - 1] != '/') {
            if (strlen(full_path) + 1 >= MAX_PATH_LEN) {
                fprintf(stderr, "Error: Path too long after getcwd.\n");
