int createFileWithSecurePermissions(const std::string& path) {
    // Use S_IRUSR | S_IWUSR for read and write permissions for the owner only.
    // This corresponds to octal 0600.
    mode_t permissions = S_IRUSR | S_IWUSR;
    int fd = open(path.c_str(), O_WRONLY | O_CREAT | O_EXCL, permissions);
