    const int iterations = 10000;
    const EVP_MD* hash_algo = EVP_sha256();
    int hash_len = EVP_MD_size(hash_algo);

    if (usernames.size() != count || passwords.size() != count) {
        throw std::invalid_argument("Usernames and passwords must match the count.");
    }

    for (int i = 0; i < count; ++i) {
        const std::string& password = passwords[i];
        std::vector<unsigned char> salt(hash_len);
        if (RAND_bytes(salt.data(), hash_len) != 1) {
            throw std::runtime_error("Failed to generate salt.");
        }

        std::vector<unsigned char> derived_key(hash_len);
