    // A more robust regex for email validation, covering common cases.
    // This regex aims to balance accuracy with avoiding catastrophic backtracking.
    // It allows for subdomains, hyphens, and dots in the local part and domain.
    const std::string email_pattern = R"(^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$)";

